package ca.loadlog.app;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;
import android.graphics.Typeface;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
    DB db; LinearLayout root, content; TextView status; String screen="home"; int exportMode=0;
    static String today(){ return new SimpleDateFormat("yyyy-MM-dd", Locale.CANADA).format(new Date()); }
    static String month(){ return new SimpleDateFormat("yyyy-MM", Locale.CANADA).format(new Date()); }
    @Override public void onCreate(Bundle b){ super.onCreate(b); db=new DB(this); showHome(); }
    int dp(float v){ return (int)(v*getResources().getDisplayMetrics().density+0.5f); }
    TextView text(String s,int size,boolean bold){ TextView t=new TextView(this); t.setText(s); t.setTextSize(size); if(bold)t.setTypeface(null,Typeface.BOLD); t.setPadding(dp(4),dp(7),dp(4),dp(7)); return t; }
    Button button(String s,Runnable r){ Button b=new Button(this); b.setText(s); b.setAllCaps(false); b.setOnClickListener(v->r.run()); return b; }
    void base(String title){
        root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackgroundColor(0xFFF5F7F6);
        TextView head=text("LoadLog  •  "+title,22,true); head.setTextColor(0xFFFFFFFF); head.setBackgroundColor(0xFF176B57); head.setPadding(dp(16),dp(18),dp(16),dp(18)); root.addView(head);
        LinearLayout nav=new LinearLayout(this); nav.setOrientation(LinearLayout.HORIZONTAL); nav.addView(button("Home",()->showHome()),new LinearLayout.LayoutParams(0,dp(48),1)); nav.addView(button("Loads",()->showLoads()),new LinearLayout.LayoutParams(0,dp(48),1)); nav.addView(button("Fuel",()->showFuel()),new LinearLayout.LayoutParams(0,dp(48),1)); nav.addView(button("Waiting",()->showWait()),new LinearLayout.LayoutParams(0,dp(48),1)); root.addView(nav);
        ScrollView scroll=new ScrollView(this); content=new LinearLayout(this); content.setPadding(dp(14),dp(10),dp(14),dp(24)); content.setOrientation(LinearLayout.VERTICAL); scroll.addView(content); root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1)); setContentView(root);
    }
    void line(String s){ content.addView(text(s,16,false)); }
    void action(String s,Runnable r){ content.addView(button(s,r)); }
    EditText field(String hint,String val){ EditText e=new EditText(this); e.setSingleLine(true); e.setHint(hint); if(val!=null)e.setText(val); e.setPadding(dp(10),dp(8),dp(10),dp(8)); content.addView(e); return e; }
    void showHome(){ screen="home"; base("Dashboard"); SQLiteDatabase d=db.getReadableDatabase(); Cursor c=d.rawQuery("SELECT COUNT(*), COALESCE(SUM(pay),0) FROM loads WHERE substr(date,1,7)=?",new String[]{month()}); c.moveToFirst(); int count=c.getInt(0); double pay=c.getDouble(1); c.close();
        line("This month • "+month()); line("Total earnings: $"+money(pay)); line("Loads completed: "+count); line("Fuel entries: "+db.count("fuel",month())); line("Waiting entries: "+db.count("waiting",month()));
        line("\nYour records are stored in an on-phone SQLite database. No internet connection is needed, and company-paid fuel is never deducted from earnings.");
        action("+ Add load",()->addLoad()); action("+ Add fuel record",()->addFuel()); action("+ Add waiting time",()->addWait()); action("Monthly report / export",()->showReport()); action("Back up records (CSV)",()->chooseExport(0)); action("Export all records (CSV)",()->chooseExport(1));
    }
    void showLoads(){ screen="loads"; base("Loads"); action("+ Add load",()->addLoad()); Cursor c=db.getReadableDatabase().rawQuery("SELECT id,date,material,pay,pickup,delivery,ticket FROM loads ORDER BY date DESC,id DESC",null); while(c.moveToNext()){ final int id=c.getInt(0); line(c.getString(1)+" • "+c.getString(2)+" • $"+money(c.getDouble(3))+"\n"+safe(c.getString(4))+" → "+safe(c.getString(5))+"  | Ticket: "+safe(c.getString(6))); action("Delete load #"+id,()->confirmDelete("loads",id,()->showLoads())); } c.close(); if(content.getChildCount()==1)line("No loads recorded yet."); }
    void showFuel(){ screen="fuel"; base("Fuel"); action("+ Add fuel record",()->addFuel()); Cursor c=db.getReadableDatabase().rawQuery("SELECT id,date,litres,station,odo,receipt FROM fuel ORDER BY date DESC,id DESC",null); while(c.moveToNext()){final int id=c.getInt(0);line(c.getString(1)+" • "+c.getDouble(2)+" L • "+safe(c.getString(3))+"\nOdometer: "+safe(c.getString(4))+" • Receipt: "+safe(c.getString(5)));action("Delete fuel #"+id,()->confirmDelete("fuel",id,()->showFuel()));} c.close();if(content.getChildCount()==1)line("No fuel records yet."); }
    void showWait(){ screen="waiting"; base("Waiting time"); action("+ Add waiting time",()->addWait()); Cursor c=db.getReadableDatabase().rawQuery("SELECT id,date,reason,start,end,minutes FROM waiting ORDER BY date DESC,id DESC",null); while(c.moveToNext()){final int id=c.getInt(0);line(c.getString(1)+" • "+safe(c.getString(2))+"\n"+safe(c.getString(3))+"–"+safe(c.getString(4))+" • "+duration(c.getInt(5)));action("Delete waiting entry #"+id,()->confirmDelete("waiting",id,()->showWait()));} c.close();if(content.getChildCount()==1)line("No waiting time recorded yet."); }
    void addLoad(){ LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);String[] labels={"Date (YYYY-MM-DD)","Material (Logs or Wood chips)","Flat rate pay ($)","Pickup location","Delivery location","Ticket / load number","Start time (HH:MM, optional)","End time (HH:MM, optional)","Notes (optional)"}; EditText[] e=new EditText[labels.length]; for(int i=0;i<labels.length;i++){e[i]=new EditText(this);e[i].setSingleLine(i!=8);e[i].setHint(labels[i]); if(i==0)e[i].setText(today());if(i==1)e[i].setText("Logs");box.addView(e[i]);} new AlertDialog.Builder(this).setTitle("Add load").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(a,b)->{String date=val(e[0],today()),mat=val(e[1],"Logs");double pay=num(e[2]);db.getWritableDatabase().execSQL("INSERT INTO loads(date,material,pay,pickup,delivery,ticket,start,end,notes) VALUES(?,?,?,?,?,?,?,?,?)",new Object[]{date,mat,pay,val(e[3],""),val(e[4],""),val(e[5],""),val(e[6],""),val(e[7],""),val(e[8],"")});showLoads();}).show(); }
    void addFuel(){ LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);String[] labels={"Date (YYYY-MM-DD)","Litres filled","Station","Odometer","Receipt / reference","Receipt total ($, optional)"};EditText[] e=new EditText[labels.length];for(int i=0;i<e.length;i++){e[i]=new EditText(this);e[i].setHint(labels[i]);e[i].setSingleLine(true);if(i==0)e[i].setText(today());box.addView(e[i]);}new AlertDialog.Builder(this).setTitle("Company-paid fuel record").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(a,b)->{db.getWritableDatabase().execSQL("INSERT INTO fuel(date,litres,station,odo,receipt,total) VALUES(?,?,?,?,?,?)",new Object[]{val(e[0],today()),num(e[1]),val(e[2],""),val(e[3],""),val(e[4],""),num(e[5])});showFuel();}).show(); }
    void addWait(){ LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);String[] labels={"Date (YYYY-MM-DD)","Reason / location","Start time (HH:MM)","End time (HH:MM)"};EditText[] e=new EditText[labels.length];for(int i=0;i<e.length;i++){e[i]=new EditText(this);e[i].setHint(labels[i]);e[i].setSingleLine(true);if(i==0)e[i].setText(today());box.addView(e[i]);}new AlertDialog.Builder(this).setTitle("Add unpaid waiting time").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(a,b)->{int mins=minutes(val(e[2],"00:00"),val(e[3],"00:00"));db.getWritableDatabase().execSQL("INSERT INTO waiting(date,reason,start,end,minutes) VALUES(?,?,?,?,?)",new Object[]{val(e[0],today()),val(e[1],""),val(e[2],"00:00"),val(e[3],"00:00"),mins});showWait();}).show(); }
    void showReport(){ base("Monthly report"); EditText m=field("Month (YYYY-MM)",month()); action("Show report",()->renderReport(m.getText().toString().trim())); action("Export this month (CSV)",()->chooseExport(2)); renderReport(month()); }
    void renderReport(String m){ if(m.length()<7){return;} SQLiteDatabase d=db.getReadableDatabase();Cursor c=d.rawQuery("SELECT COUNT(*),COALESCE(SUM(pay),0),SUM(CASE WHEN lower(material) LIKE '%log%' THEN 1 ELSE 0 END),SUM(CASE WHEN lower(material) LIKE '%chip%' THEN 1 ELSE 0 END) FROM loads WHERE substr(date,1,7)=?",new String[]{m});c.moveToFirst();int n=c.getInt(0);double earnings=c.getDouble(1);int logs=c.getInt(2),chips=c.getInt(3);c.close();Cursor w=d.rawQuery("SELECT COALESCE(SUM(minutes),0),COUNT(*) FROM waiting WHERE substr(date,1,7)=?",new String[]{m});w.moveToFirst();int mins=w.getInt(0),wc=w.getInt(1);w.close();Cursor f=d.rawQuery("SELECT COUNT(*),COALESCE(SUM(litres),0) FROM fuel WHERE substr(date,1,7)=?",new String[]{m});f.moveToFirst();int fc=f.getInt(0);double litres=f.getDouble(1);f.close();line("\nREPORT: "+m);line("TOTAL EARNINGS: $"+money(earnings));line("Loads completed: "+n);line("Logs loads: "+logs);line("Wood chips loads: "+chips);line("Unpaid waiting time: "+duration(mins)+" across "+wc+" entries");line("Company-paid fuel: "+fc+" records / "+String.format(Locale.CANADA,"%.1f",litres)+" L (not deducted)"); }
    void confirmDelete(String table,int id,Runnable done){new AlertDialog.Builder(this).setMessage("Delete this record? This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(a,b)->{db.getWritableDatabase().delete(table,"id=?",new String[]{String.valueOf(id)});done.run();}).show();}
    void chooseExport(int mode){exportMode=mode;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"LoadLog_"+(mode==2?month():"records")+".csv");startActivityForResult(i,20);}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==20&&result==RESULT_OK&&data!=null){try{OutputStream os=getContentResolver().openOutputStream(data.getData());OutputStreamWriter out=new OutputStreamWriter(os);if(exportMode==0||exportMode==1)exportTable(out,"loads",new String[]{"id","date","material","pay","pickup","delivery","ticket","start","end","notes"},exportMode==0?null:null);if(exportMode==0||exportMode==1){out.write("\nFUEL RECORDS\n");exportTable(out,"fuel",new String[]{"id","date","litres","station","odo","receipt","total"},null);out.write("\nWAITING RECORDS\n");exportTable(out,"waiting",new String[]{"id","date","reason","start","end","minutes"},null);}if(exportMode==2){String m=month();out.write("Monthly report,"+m+"\nTotal earnings,"+monthlyPay(m)+"\n");out.write("\nLOADS\n");exportTable(out,"loads",new String[]{"id","date","material","pay","pickup","delivery","ticket","start","end","notes"},m);out.write("\nFUEL RECORDS (company-paid; not deducted)\n");exportTable(out,"fuel",new String[]{"id","date","litres","station","odo","receipt","total"},m);out.write("\nWAITING RECORDS\n");exportTable(out,"waiting",new String[]{"id","date","reason","start","end","minutes"},m);}out.flush();out.close();Toast.makeText(this,"CSV exported",Toast.LENGTH_LONG).show();}catch(Exception ex){Toast.makeText(this,"Export failed: "+ex.getMessage(),Toast.LENGTH_LONG).show();}}}
    double monthlyPay(String m){Cursor c=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(pay),0) FROM loads WHERE substr(date,1,7)=?",new String[]{m});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}
    void exportTable(OutputStreamWriter out,String table,String[] cols,String monthFilter)throws Exception{StringBuilder q=new StringBuilder("SELECT ");for(int i=0;i<cols.length;i++){if(i>0)q.append(',');q.append(cols[i]);}q.append(" FROM ").append(table);if(monthFilter!=null)q.append(" WHERE substr(date,1,7)=?");q.append(" ORDER BY date,id");Cursor c=db.getReadableDatabase().rawQuery(q.toString(),monthFilter==null?null:new String[]{monthFilter});out.write(csvLine(cols));while(c.moveToNext()){String[] row=new String[cols.length];for(int i=0;i<cols.length;i++)row[i]=c.isNull(i)?"":c.getString(i);out.write(csvLine(row));}c.close();}
    String csvLine(String[] a){StringBuilder s=new StringBuilder();for(int i=0;i<a.length;i++){if(i>0)s.append(',');String v=a[i]==null?"":a[i];s.append('"').append(v.replace("\"","\"\"")).append('"');}return s+"\n";}
    static String val(EditText e,String def){String s=e.getText().toString().trim();return s.isEmpty()?def:s;}static double num(EditText e){try{return Double.parseDouble(e.getText().toString().trim());}catch(Exception x){return 0;}}static String money(double x){return String.format(Locale.CANADA,"%.2f",x);}static String safe(String s){return s==null||s.isEmpty()?"—":s;}static String duration(int m){return (m/60)+" h "+(m%60)+" min";}static int minutes(String a,String b){try{String[] x=a.split(":"),y=b.split(":");int s=Integer.parseInt(x[0])*60+Integer.parseInt(x[1]),e=Integer.parseInt(y[0])*60+Integer.parseInt(y[1]);if(e<s)e+=1440;return e-s;}catch(Exception ex){return 0;}}
    static class DB extends SQLiteOpenHelper{DB(Context c){super(c,"loadlog.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE loads(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,material TEXT,pay REAL,pickup TEXT,delivery TEXT,ticket TEXT,start TEXT,end TEXT,notes TEXT)");d.execSQL("CREATE TABLE fuel(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,litres REAL,station TEXT,odo TEXT,receipt TEXT,total REAL)");d.execSQL("CREATE TABLE waiting(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,reason TEXT,start TEXT,end TEXT,minutes INTEGER)");}public void onUpgrade(SQLiteDatabase d,int o,int n){} int count(String table,String m){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM "+table+" WHERE substr(date,1,7)=?",new String[]{m});c.moveToFirst();int n=c.getInt(0);c.close();return n;}}
}
